  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 9, $j$3.1 Paul the Letter Writer and Romans: Sin and Grace$j$, $j${"readings": [{"title": "Romans 3 (King James Version)", "url": "/portal/bible/Romans/3"}, {"title": "Romans 5 (King James Version)", "url": "/portal/bible/Romans/5"}, {"title": "Romans 6 (King James Version)", "url": "/portal/bible/Romans/6"}], "body": "Read Romans 3, Romans 5 and Romans 6 in the King James Version. Then read this lesson.\n\nThirteen of the twenty seven books of the New Testament are letters written by the apostle Paul. These letters, called epistles, were sent to churches and to friends to teach, correct and encourage. They were written to real people facing real problems, and they are arranged in the Bible by length, not by date. The longest and most important is Romans, written to the church in Rome. Romans explains the gospel. All people have sinned, no one can earn salvation by good works, and God gives righteousness freely by grace through faith in Jesus Christ. The wages of sin is death, but the gift of God is eternal life.\n\nKey words: epistle, sin, grace, justified, faith.\n\nYour task: (1) Explain what an epistle is and who wrote thirteen of them. (2) Write Romans 3:23 in your own words. (3) Tell the difference between the wages of sin and the gift of God in Romans 6:23.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Welcome to Unit 3. The Gospels told us what Jesus did, and Acts told us how the church began. Now we study the letters. A letter in the New Testament is called an epistle, and the epistles explain what the good news means for daily life.\n\nThirteen of these letters were written by the apostle Paul, the man who was once Saul the persecutor. Paul wrote to churches he had started and to friends like Timothy, and he wrote about real problems, such as division, false teaching and fear. The letters are arranged in the Bible from the longest to the shortest, not by the date they were written. The longest is Romans, and it is the most complete explanation of the gospel in the Bible.\n\nPaul wrote Romans to the believers in Rome, a city he had not yet visited. He began by saying in Romans 1:16, I am not ashamed of the gospel of Christ: for it is the power of God unto salvation to every one that believeth. Then he gave the bad news first. Both Jews and Gentiles have a problem. Romans 3:23 says, For all have sinned, and come short of the glory of God. Nobody can reach God by their own goodness.\n\nThen comes the good news. Romans 3:24 says, Being justified freely by his grace through the redemption that is in Christ Jesus. To be justified means to be declared right with God, as if we had never sinned. It is a free gift that we receive by faith. Paul pointed to the greatest proof of God's love in Romans 5:8, But God commendeth his love toward us, in that, while we were yet sinners, Christ died for us.\n\nPaul also made clear that grace is never an excuse to keep on sinning. In Romans 6:23 he wrote, For the wages of sin is death; but the gift of God is eternal life through Jesus Christ our Lord. Wages are what you earn, and a gift is something you cannot earn. Sin pays death, and God offers life as a gift.\n\nYour task is to explain what an epistle is, write Romans 3:23 in your own words, and tell the difference between wages and a gift. Then take the four question check.\n\nSalvation is a gift that we receive, never a wage that we earn. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.1 Paul the Letter Writer and Romans: Sin and Grace$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 10, $j$3.2 Romans: Life in the Spirit$j$, $j${"readings": [{"title": "Romans 8 (King James Version)", "url": "/portal/bible/Romans/8"}, {"title": "Romans 10 (King James Version)", "url": "/portal/bible/Romans/10"}, {"title": "Romans 12 (King James Version)", "url": "/portal/bible/Romans/12"}], "body": "Read Romans 8, Romans 10 and Romans 12 in the King James Version. Then read this lesson.\n\nAfter explaining grace, Paul showed how believers are to live. Romans 8 is one of the best loved chapters in the Bible. It says that there is no condemnation to those who are in Christ Jesus, who walk after the Spirit, and that all things work together for good to those who love God. In Romans 10 Paul explained that anyone who confesses the Lord Jesus and believes in the heart that God raised Him from the dead will be saved, and that faith comes by hearing the word of God. In Romans 12 he urged believers to give their lives to God as a living sacrifice and to be transformed by the renewing of the mind.\n\nKey words: condemnation, Spirit, confess, sacrifice, renewing.\n\nYour task: (1) Write Romans 8:1 in your own words. (2) Explain how faith comes, according to Romans 10:17. (3) Tell what Romans 12:2 says we are to be and not to be.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Last time we saw that salvation is a gift of grace. Today we see how Paul says that gift changes the way we live. Romans 8 is one of the most comforting chapters in the whole Bible.\n\nRomans 8:1 says, There is therefore now no condemnation to them which are in Christ Jesus, who walk not after the flesh, but after the Spirit. Condemnation means the judgment of guilt. For those in Christ Jesus, the guilt has been taken away. Paul then explained that the Spirit of God lives in believers, helps them in their weakness and prays for them. He also gave a promise in Romans 8:28, And we know that all things work together for good to them that love God, to them who are the called according to his purpose. That does not mean everything that happens is good. It means that God uses even hard things for the good of those who love Him.\n\nIn Romans 10 Paul wrote about how people come to salvation. Verse 9 says, That if thou shalt confess with thy mouth the Lord Jesus, and shalt believe in thine heart that God hath raised him from the dead, thou shalt be saved. Then he asked how people can believe without hearing, and how they can hear without a preacher. Romans 10:17 says, So then faith cometh by hearing, and hearing by the word of God. That is why reading and preaching the Word matters so much.\n\nRomans 12 begins the practical part of the letter. Verse 1 says, present your bodies a living sacrifice, holy, acceptable unto God, which is your reasonable service. In the Old Testament animals were killed on the altar. Now believers give their whole lives to God each day. Then Paul said in verse 2, And be not conformed to this world: but be ye transformed by the renewing of your mind. We do not copy the pattern of the world. God changes us from the inside, and it starts with the way we think.\n\nYour task is to write Romans 8:1 in your own words, explain how faith comes, and tell what Romans 12:2 says we are to be and not to be. Then take the four question check.\n\nGod changes us from the inside out. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.2 Romans: Life in the Spirit$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 11, $j$3.3 First and Second Corinthians$j$, $j${"readings": [{"title": "1 Corinthians 12 (King James Version)", "url": "/portal/bible/1Corinthians/12"}, {"title": "1 Corinthians 13 (King James Version)", "url": "/portal/bible/1Corinthians/13"}, {"title": "1 Corinthians 15 (King James Version)", "url": "/portal/bible/1Corinthians/15"}, {"title": "2 Corinthians 5 (King James Version)", "url": "/portal/bible/2Corinthians/5"}, {"title": "2 Corinthians 12 (King James Version)", "url": "/portal/bible/2Corinthians/12"}], "body": "Read 1 Corinthians 12, 1 Corinthians 13, 1 Corinthians 15, 2 Corinthians 5 and 2 Corinthians 12 in the King James Version. Then read this lesson.\n\nCorinth was a large and wealthy Greek port city, and the church there was gifted but divided. Paul wrote to correct problems such as quarrels, misuse of spiritual gifts and confusion about the resurrection. In 1 Corinthians 12 he taught that the church is one body with many members. In chapter 13 he showed that love is greater than any gift, and that faith, hope and charity remain, but the greatest is charity. In chapter 15 he gave the gospel: Christ died for our sins, was buried and rose again the third day. In 2 Corinthians he wrote about new life in Christ and about how God's grace is sufficient in weakness.\n\nKey words: body, gifts, charity, resurrection, new creature.\n\nYour task: (1) Tell what Paul meant when he called the church the body of Christ. (2) Say which is the greatest of faith, hope and charity. (3) Write 2 Corinthians 5:17 in your own words.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "Corinth was a busy Greek port city, known for its wealth and its wild living. Paul spent a year and a half there and started a church, and then he wrote at least two letters to it that we still have. The church at Corinth had many gifts, but it also had many problems. Some members were quarreling, some were proud of their gifts, and some doubted the resurrection.\n\nIn First Corinthians 12 Paul used the picture of a body. He said in verse 27, Now ye are the body of Christ, and members in particular. A body has many parts, and every part matters. The eye cannot say to the hand, I have no need of thee. Every believer has a place and a gift, and the gifts are to build up the whole church.\n\nThen Paul gave what we call the love chapter. In chapter 13 he said that you can speak with tongues, have great faith and give away everything, but if you do not have love, you are nothing. Verse 13 says, And now abideth faith, hope, charity, these three; but the greatest of these is charity. The word charity here means love.\n\nIn chapter 15 Paul reminded the church of the gospel itself. He wrote in verses 3 and 4, Christ died for our sins according to the scriptures; And that he was buried, and that he rose again the third day according to the scriptures. Paul said that if Christ has not been raised, our faith is empty. But Christ has been raised, and so we will be raised too.\n\nIn Second Corinthians Paul wrote in a more personal way. He said in chapter 5 and verse 17, Therefore if any man be in Christ, he is a new creature: old things are passed away; behold, all things are become new. He also shared that he had a thorn in the flesh and prayed three times for it to be taken away. God answered in 2 Corinthians 12:9, My grace is sufficient for thee: for my strength is made perfect in weakness. Our weakness is the place where God shows His strength.\n\nYour task is to tell what Paul meant by the body of Christ, say which is the greatest of faith, hope and charity, and write 2 Corinthians 5:17 in your own words. Then take the four question check.\n\nIn Christ we are one body, and in Christ we are made new. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.3 First and Second Corinthians$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 12, $j$3.4 Galatians: Faith and Freedom$j$, $j${"readings": [{"title": "Galatians 2 (King James Version)", "url": "/portal/bible/Galatians/2"}, {"title": "Galatians 3 (King James Version)", "url": "/portal/bible/Galatians/3"}, {"title": "Galatians 5 (King James Version)", "url": "/portal/bible/Galatians/5"}], "body": "Read Galatians 2, Galatians 3 and Galatians 5 in the King James Version. Then read this lesson.\n\nPaul wrote Galatians to churches in Asia Minor that were being led astray by teachers who said Gentile believers had to keep the law of Moses to be saved. Paul answered that a person is justified by faith in Jesus Christ, not by works of the law. He said that he was crucified with Christ and that Christ lives in him. Because of faith in Christ, all believers are children of God. Galatians 5 urges believers to stand fast in the liberty with which Christ has made them free, and it lists the fruit of the Spirit, which is love, joy, peace, longsuffering, gentleness, goodness, faith, meekness and temperance.\n\nKey words: justified, law, liberty, fruit of the Spirit, faith.\n\nYour task: (1) Tell why Paul wrote Galatians. (2) Write Galatians 2:20 in your own words. (3) Name at least five parts of the fruit of the Spirit from Galatians 5:22 and 23.\n\nCourse area: Bible elective. Scripture is read from the King James Version.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Bible elective", "script": "The last letter in this unit is Galatians, and it is one of Paul's most passionate letters. He wrote to churches in the region of Galatia, and he was upset. Some teachers had come after Paul left and said that Gentile believers had to keep the law of Moses and be circumcised in order to be saved. Paul called that another gospel and said it was no gospel at all.\n\nPaul answered by pointing to the cross. He wrote in Galatians 2:20, I am crucified with Christ: nevertheless I live; yet not I, but Christ liveth in me. The old self is dead, and now Christ lives in the believer. A person is justified, or made right with God, by faith in Jesus Christ and not by keeping the law.\n\nPaul asked the Galatians a plain question in chapter 3. They had received the Spirit by hearing with faith, so why would they now try to finish in the flesh what they began in the Spirit? He reminded them that Abraham was counted righteous because he believed God. Galatians 3:26 says, For ye are all the children of God by faith in Christ Jesus. Nothing makes a person a child of God except faith in Jesus Christ.\n\nIn chapter 5 Paul turned to freedom. Galatians 5:1 says, Stand fast therefore in the liberty wherewith Christ hath made us free. Freedom is not a license to do anything we want. It is freedom to love and serve one another. Paul then compared the works of the flesh to the fruit of the Spirit. Galatians 5:22 and 23 says, But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith, Meekness, temperance. Notice that it says fruit, in the singular. A tree does not make fruit by trying hard. Fruit grows when the tree is healthy, and it grows in believers who walk in the Spirit.\n\nYour task is to tell why Paul wrote Galatians, write Galatians 2:20 in your own words, and name at least five parts of the fruit of the Spirit. Then take the four question check and the Unit 3 quiz.\n\nWe are saved by faith, and we grow by the Spirit. Excellence, Faith, Purpose. I will see you in the next unit."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$3.4 Galatians: Faith and Freedom$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 3, $j$Assessment 3: A Verse from Paul's Letters$j$, $j${"prompt": "Choose one verse from this unit: Romans 3:23, Romans 6:23, Romans 8:1, Romans 12:2, 1 Corinthians 13:13, 2 Corinthians 5:17, Galatians 2:20 or Galatians 5:22 and 23. Write one paragraph of 150 to 200 words. Quote the verse from the King James Version, explain what it means in its letter, and tell how a student today can live it out.", "rubric": "Total 100. Accurate quotation of the verse with the reference: 20. Explains the meaning in the context of the letter: 30. Applies the verse to student life: 30. Clear writing and correct conventions: 20."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 3: A Verse from Paul's Letters$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 3, $j$Discussion 3: Grace and Change$j$, $j${"prompt": "Paul taught that we are saved by grace through faith and then changed from the inside by the Spirit. Think of one area of your life where you want to see change. Describe it and explain how a truth from Paul's letters in this unit could help. Respond in 100 to 150 words."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 3: Grace and Change$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 11, $j$Check 3.1: Paul the Letter Writer and Romans: Sin and Grace$j$, $j${"questions": [{"q": "What is an epistle?", "options": ["A story about Jesus", "A letter in the New Testament", "A prayer of the church", "A list of laws"]}, {"q": "Which apostle wrote thirteen of the New Testament letters?", "options": ["James", "John", "Paul", "Peter"]}, {"q": "According to Romans 3:23, who has sinned and come short of the glory of God?", "options": ["All", "Only the wicked", "Only the Gentiles", "Only the unbelievers"]}, {"q": "What does Romans 6:23 call the gift of God?", "options": ["Eternal life through Jesus Christ our Lord", "A seat in the temple", "Wealth", "A long life on earth"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Paul the Letter Writer and Romans: Sin and Grace$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,0,0}'::int[], array[$j$An epistle is a letter, and many New Testament books are epistles.$j$,$j$Paul wrote thirteen epistles, from Romans to Philemon.$j$,$j$Romans 3:23 says all have sinned.$j$,$j$The wages of sin is death, but the gift of God is eternal life.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.1: Paul the Letter Writer and Romans: Sin and Grace$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 12, $j$Check 3.2: Romans: Life in the Spirit$j$, $j${"questions": [{"q": "What does Romans 8:1 say about those who are in Christ Jesus?", "options": ["There is no condemnation", "They will be rich", "They will never be tested", "They must keep the law first"]}, {"q": "According to Romans 10:17, how does faith come?", "options": ["By good works", "By hearing, and hearing by the word of God", "By feeling it", "By earning it"]}, {"q": "What does Romans 12:1 ask believers to present to God?", "options": ["A tenth of the harvest", "Gold and silver", "A new temple", "Their bodies as a living sacrifice"]}, {"q": "According to Romans 12:2, how are believers transformed?", "options": ["By renewing their mind", "By moving away", "By working harder", "By following the world"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Romans: Life in the Spirit$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,3,0}'::int[], array[$j$Romans 8:1 says there is no condemnation to them which are in Christ Jesus.$j$,$j$Faith comes by hearing the word of God.$j$,$j$Believers are to give their lives to God as a living sacrifice.$j$,$j$Romans 12:2 says be transformed by the renewing of your mind.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.2: Romans: Life in the Spirit$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 13, $j$Check 3.3: First and Second Corinthians$j$, $j${"questions": [{"q": "What picture did Paul use in 1 Corinthians 12 to describe the church?", "options": ["A vineyard", "A building", "A body with many members", "A flock of sheep"]}, {"q": "According to 1 Corinthians 13:13, which is the greatest of faith, hope and charity?", "options": ["Charity", "They are all equal", "Faith", "Hope"]}, {"q": "What did Paul say in 1 Corinthians 15 about Christ?", "options": ["He rose again the third day", "He never died", "He lived only as a teacher", "He stayed in the tomb"]}, {"q": "What did God tell Paul in 2 Corinthians 12:9?", "options": ["Leave Corinth", "Your thorn will be removed tomorrow", "Build a temple", "My grace is sufficient for thee"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: First and Second Corinthians$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,0,3}'::int[], array[$j$Paul said, Now ye are the body of Christ, and members in particular.$j$,$j$The greatest of these is charity, which means love.$j$,$j$Paul wrote that Christ died, was buried and rose again the third day.$j$,$j$God said that His grace is sufficient and His strength is made perfect in weakness.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.3: First and Second Corinthians$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 14, $j$Check 3.4: Galatians: Faith and Freedom$j$, $j${"questions": [{"q": "Why did Paul write the letter to the Galatians?", "options": ["To ask for money", "To correct teachers who said Gentiles must keep the law to be saved", "To describe his travels", "To plan a visit to Rome"]}, {"q": "According to Galatians 2:20, who lives in the believer?", "options": ["Moses", "The law", "Christ", "The prophets"]}, {"q": "What does Galatians 5:1 tell believers to do?", "options": ["Wait in Jerusalem", "Build an altar", "Stand fast in the liberty wherewith Christ hath made us free", "Return to the law"]}, {"q": "Which of these is part of the fruit of the Spirit in Galatians 5:22 and 23?", "options": ["Love", "Wealth", "Power", "Pride"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Galatians: Faith and Freedom$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,2,0}'::int[], array[$j$Paul defended the gospel of faith against teachers who added the law.$j$,$j$Paul wrote, Christ liveth in me.$j$,$j$Paul urged believers to stand fast in their freedom in Christ.$j$,$j$Love is the first fruit of the Spirit listed.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 3.4: Galatians: Faith and Freedom$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 15, $j$Unit Quiz 3: Paul's Letters, Part One, Romans to Galatians$j$, $j${"questions": [{"q": "What is the longest and most complete explanation of the gospel among Paul's letters?", "options": ["Philemon", "Galatians", "Romans", "Titus"]}, {"q": "What does Romans 6:23 say is the wages of sin?", "options": ["Peace", "Death", "Life", "Joy"]}, {"q": "According to Romans 10:17, faith comes by what?", "options": ["Working hard", "Giving", "Feeling", "Hearing the word of God"]}, {"q": "Which chapter of First Corinthians is called the love chapter?", "options": ["Chapter 12", "Chapter 15", "Chapter 1", "Chapter 13"]}, {"q": "What did Paul say in 2 Corinthians 5:17 about anyone in Christ?", "options": ["He will leave the world", "He must keep the law", "He will never suffer", "He is a new creature"]}, {"q": "What does the book of Galatians teach about how a person is justified?", "options": ["By faith in Jesus Christ", "By being born in Israel", "By paying tithes", "By works of the law"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Paul's Letters, Part One, Romans to Galatians$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,3,3,3,0}'::int[], array[$j$Romans is the longest and explains grace and faith in detail.$j$,$j$The wages of sin is death, but the gift of God is eternal life.$j$,$j$Faith cometh by hearing, and hearing by the word of God.$j$,$j$First Corinthians 13 teaches that love is greater than every gift.$j$,$j$Paul wrote that old things are passed away and all things are become new.$j$,$j$Paul taught that a person is justified by faith in Jesus Christ.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 3: Paul's Letters, Part One, Romans to Galatians$j$ on conflict (item_id) do nothing;
